using System.Collections.Generic;

namespace SuperKRWKMod.ModList
{
	/// <summary>
	/// Mod text in the game's other languages, keyed by the English text used at the call site
	/// (English and Japanese live in the code). Each row: English key, then one entry per language
	/// in <see cref="Languages"/> order. Hebrew is left out on purpose (right-to-left text) and falls
	/// back to English. Fixes and new languages are welcome as pull requests.
	/// </summary>
	public static class Translations
	{
		private static readonly string[] Languages =
		{
			"zh-CN", "zh-TW", "ko", "es", "fr", "de", "pt", "ru", "it", "pl", "tr",
			"uk", "nl", "cs", "da", "fi", "el", "hu", "no", "ro", "sv",
		};

		private static Dictionary<string, Dictionary<string, string>> _byLanguage;

		/// <summary>The translation, or null if there is none.</summary>
		public static string Lookup(string language, string english)
		{
			if (_byLanguage == null)
				Build();

			return _byLanguage.TryGetValue(language, out var table) && table.TryGetValue(english, out var text) ? text : null;
		}

		private static void Build()
		{
			_byLanguage = new Dictionary<string, Dictionary<string, string>>();
			foreach (var language in Languages)
				_byLanguage[language] = new Dictionary<string, string>();

			foreach (var row in Rows)
			{
				for (int i = 0; i < Languages.Length && i + 1 < row.Length; i++)
				{
					if (!string.IsNullOrEmpty(row[i + 1]))
						_byLanguage[Languages[i]][row[0]] = row[i + 1];
				}
			}
		}

